import{_ as l}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as i,o as e,af as t}from"./chunks/mermaid.YsAH9es0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Agent 调优实践卡：从轨迹数据到受控自进化","description":"把阿里云《AI Agent Handbook》第 17–24 章转成 8 张可执行实践卡：模型调优归因、数据飞轮、轨迹数据、运行时 Pipeline、黄金数据集、Badcase 评估与实验、受控自进化、边缘运行时与全球优化。每张卡含做法、前置条件、边界、反例、效果指标、逐字引用与一人团队降级路径。","frontmatter":{"title":"Agent 调优实践卡：从轨迹数据到受控自进化","description":"把阿里云《AI Agent Handbook》第 17–24 章转成 8 张可执行实践卡：模型调优归因、数据飞轮、轨迹数据、运行时 Pipeline、黄金数据集、Badcase 评估与实验、受控自进化、边缘运行时与全球优化。每张卡含做法、前置条件、边界、反例、效果指标、逐字引用与一人团队降级路径。","domain":"practice","tags":["agent","tuning","evaluation","dataset","observability","distillation","rl"],"listed":true,"outline":false},"headers":[],"relativePath":"zh/practice/agent-handbook/optimization.md","filePath":"zh/practice/agent-handbook/optimization.md","lastUpdated":1792458633000}'),o={name:"zh/practice/agent-handbook/optimization.md"};function r(n,a,h,s,u,d){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="agent-调优实践卡" tabindex="-1">Agent 调优实践卡 <a class="header-anchor" href="#agent-调优实践卡" aria-label="Permalink to &quot;Agent 调优实践卡&quot;">​</a></h1><blockquote><p>来源：阿里云《AI Agent Handbook》第 17–24 章（模型调优、Agent 调优总览、轨迹数据、运行时数据处理、黄金数据集、Badcase、受控自进化、边缘运行时与全球优化）。 读法：每章一张卡，按「要解决什么问题 → 怎么做 → 做到什么程度算好」组织；卡片之间是流水线关系（17 改模型 → 19/20 生产数据 → 21/22 评估与实验 → 23 沉淀方法 → 24 全球化扩展）。 标注约定：<strong>✦ = 阿里云团队主张 / 内部数据 / 示例场景假设</strong>，只可参考、必须用自己的基线校准；<strong>◇ = 手册引用的第三方公开数据</strong>（论文、厂商报告），同样不是本业务的实测；无标注的方法是通用工程实践，任何团队可独立复现。</p></blockquote><h2 id="与现有页面的关系-以及插入位置" tabindex="-1">与现有页面的关系，以及插入位置 <a class="header-anchor" href="#与现有页面的关系-以及插入位置" aria-label="Permalink to &quot;与现有页面的关系，以及插入位置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现有页面</th><th>重叠点</th><th>处理方式</th></tr></thead><tbody><tr><td><code>docs/zh/practice/index.md</code>（企业实践目录）</td><td>该目录按决策顺序组织（看形势 → 怎么买），目前没有「买完之后怎么持续调优」的一层</td><td><strong>本页即补这一层</strong>。建议在 index.md 的「2. 再决定怎么买」段落后追加一行：<code>调优与评估闭环：[Agent 调优实践卡](/zh/practice/agent-tuning-practice) — 8 张可执行卡，覆盖归因、轨迹、题库、评估、自进化与边缘优化。</code>「不是本主题」段保持不变（提示怎么写仍归 <code>/zh/tech/prompt/</code>）。</td></tr><tr><td><code>docs/practice/ai-efficiency-practice.md</code>（齐淼树 AI 提效实践）</td><td>该页的「人工审核节点」「Prompt 即需求文档」正是本页卡 22（Badcase 评估）与卡 19（轨迹）的低配形态；结论不重复</td><td>建议在该页末尾追加一行反链：<code>→ 想把「人工审核节点」升级为可重复的评估闭环，看 [Agent 调优实践卡](/zh/practice/agent-tuning-practice)。</code></td></tr></tbody></table><p><strong>新页面路径建议</strong>：<code>docs/zh/practice/agent-tuning-practice.md</code>，与现有 practice 页同级。</p><hr><h2 id="卡-17-模型调优-先归因到层-再选训练方法" tabindex="-1">卡 17　模型调优：先归因到层，再选训练方法 <a class="header-anchor" href="#卡-17-模型调优-先归因到层-再选训练方法" aria-label="Permalink to &quot;卡 17　模型调优：先归因到层，再选训练方法&quot;">​</a></h2><h3 id="要解决的问题" tabindex="-1">要解决的问题 <a class="header-anchor" href="#要解决的问题" aria-label="Permalink to &quot;要解决的问题&quot;">​</a></h3><p>Agent 出错时直接想到「换模型/训模型」，但工具协议含混、上下文缺失、权限失效、外部服务异常都不是模型问题。选错优化层，训练只会把系统缺陷固化进参数。</p><h3 id="具体做法-步骤-机制-指标" tabindex="-1">具体做法（步骤 / 机制 / 指标） <a class="header-anchor" href="#具体做法-步骤-机制-指标" aria-label="Permalink to &quot;具体做法（步骤 / 机制 / 指标）&quot;">​</a></h3><ol><li><strong>三层归因（模型 / Harness / 执行环境）</strong>，按固定顺序排查：先排除能够独立复现的执行环境故障，再检查 Harness 的信息与运行控制，最后才判断模型能力缺口（原书表 17.1-1 给出每层的验证方法：绕过模型直调工具、固定模型改 Harness、固定 Harness 换模型）。</li><li><strong>把「效果不好」拆成四类可训练的能力缺口</strong>：任务理解与约束识别、工具使用与反馈理解、多步决策与状态利用、失败恢复与合理终止。</li><li><strong>指标三件套 + 安全护栏</strong>：质量（端到端任务成功率、关键动作正确性）、可靠性（同任务多次运行的波动）、成本（单位成功任务成本，失败任务的消耗也计入分子）、安全（越权与约束穿透单独报告）。</li><li><strong>方法选择树</strong>：有可示范的正确行为 → SFT；存在多条可行路径且环境能给可验证反馈 → Agentic RL；教师已具备能力且目标是迁移/降本 → 蒸馏。三者可组合（蒸馏通常由教师数据上的 SFT 实现）。</li><li><strong>SFT 样本纪律</strong>：只监督「经验证的行为」；错误动作保留在上下文里帮模型理解为何修正，但屏蔽其训练损失；样本覆盖正常执行、多轮推进、异常恢复三类。</li><li><strong>Agentic RL 准入</strong>（原书表 17.3-1）：任务可重复执行、状态可重置、探索可隔离、过程可追踪；结果可验证比过程可标注更重要。奖励 = 任务结果 + 关键过程 − 执行成本 − 约束违反；训练奖励、独立评测、系统硬约束三者分离。</li><li><strong>蒸馏两路线</strong>：黑盒序列级（只要教师文本/轨迹，跨 tokenizer 可用，企业主流）与白盒分布级（要 logits/log-prob，监督更稠密）。高风险任务保留教师校验；收益用「单位成功任务成本」核算，不只看 token 单价。</li><li><strong>上线五道门禁</strong>：接口兼容、目标收益、能力回归（非劣效界值）、运行预算、安全硬门禁；灰度按影子验证 → 低风险灰度 → 分阶段扩量 → 稳定替换，回滚单位是「模型 + Harness + 环境」整个发布单元。</li></ol><h3 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h3><ul><li>已能量化区分「模型缺陷」与「Harness/环境缺陷」（按表 17.1-1 的验证方法做过对照）。</li><li>任务分布稳定到值得投入数据与训练成本；训练条件与生产条件一致或被可靠适配。</li></ul><h3 id="适用边界" tabindex="-1">适用边界 <a class="header-anchor" href="#适用边界" aria-label="Permalink to &quot;适用边界&quot;">​</a></h3><ul><li>低频、快速变化的任务：轻量 Harness 调整通常比训练更经济。</li><li>路径优劣无法可靠验证时不要上 RL——不可靠反馈会把偏差固化进策略。</li><li>教师本身不稳定的任务不要蒸馏，只会更高效地复制错误。</li></ul><h3 id="反例-失败模式" tabindex="-1">反例 / 失败模式 <a class="header-anchor" href="#反例-失败模式" aria-label="Permalink to &quot;反例 / 失败模式&quot;">​</a></h3><ul><li>把「字段含义没给到模型」当模型能力差，训完模型「猜得更好看」，根因仍在。</li><li>蒸馏后 token 单价下降，但学生规划变差、重试增多，单位成功任务成本反而上升。</li><li>训练奖励升高、独立成功率没动——奖励被投机（reward hacking）或验证器有漏洞。</li></ul><h3 id="可验证的效果指标" tabindex="-1">可验证的效果指标 <a class="header-anchor" href="#可验证的效果指标" aria-label="Permalink to &quot;可验证的效果指标&quot;">​</a></h3><ul><li>端到端任务成功率（含困难任务，固定任务构成比较）。</li><li>单位成功任务成本 = 统计期内全部任务执行成本 ÷ 成功任务数（分子含失败与重试）。</li><li>能力回归：核心通用能力非劣效；安全：越权尝试与约束拦截分别报告。</li></ul><h3 id="原文引用-逐字" tabindex="-1">原文引用（逐字） <a class="header-anchor" href="#原文引用-逐字" aria-label="Permalink to &quot;原文引用（逐字）&quot;">​</a></h3><ul><li>归因顺序：&quot;先排除能够独立复现的执行环境故障，再检查 Harness 是否提供了充分的信息和可靠的运行控制，最后判断是否属于模型能力缺口。&quot;</li><li>归因到 Harness 的判据：&quot;若必要信息缺失、工具协议含混、状态不可见或反馈被截断，应优先修复 Harness&quot;</li><li>单位成功任务成本：&quot;可采用“单位成功任务成本”，即统计期内全部任务的执行成本除以成功完成的任务数量，失败任务消耗的资源也计入分子。&quot;</li><li>SFT 样本处理：&quot;可以将错误动作保留在历史上下文中，使模型理解当前为何需要修正，但屏蔽该错误动作对应的训练损失，只监督经过验证的后续行为。&quot;</li><li>算法与设计的关系：&quot;算法不能弥补任务和奖励设计缺陷。&quot;</li><li>蒸馏核算：&quot;只比较 token 单价，会忽略学生因规划能力下降而产生的额外步骤和失败重试。&quot;</li><li>蒸馏边界：&quot;若教师在某类任务上本身不稳定，蒸馏只会更高效地复制其错误。&quot;</li></ul><h3 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to &quot;来源&quot;">​</a></h3><p><a href="https://raw.githubusercontent.com/aliyun/ai-agent-handbook/HEAD/05-optimization/%E7%AC%AC%2017%20%E7%AB%A0%E3%80%80%E6%A8%A1%E5%9E%8B%E8%B0%83%E4%BC%98.md" target="_blank" rel="noreferrer">第 17 章　模型调优</a>（17.1 归因与指标、17.2 SFT、17.3 Agentic RL、17.4 蒸馏、17.5 验收上线）</p><h3 id="阿里云主张-第三方数据-不可直接当基准" tabindex="-1">阿里云主张 / 第三方数据（不可直接当基准） <a class="header-anchor" href="#阿里云主张-第三方数据-不可直接当基准" aria-label="Permalink to &quot;阿里云主张 / 第三方数据（不可直接当基准）&quot;">​</a></h3><ul><li>✦ AgentDistill 实验、PAI EasyDistill 的难度分箱配比、PAI-EAS 灰度能力：阿里云平台内部实践，方法与数字供参考。</li><li>◇ Prodinit 案例称推理成本估算下降约 70%（厂商案例）；FrugalGPT 称最高降约 98% 成本；Thinking Machines Lab 的 OPD 效率结论仅限特定数学推理设置。均为手册转引，非普适收益。</li><li>通用可复现部分：三层归因、四类能力缺口、单位成功任务成本、RL 准入条件、黑白盒蒸馏选择、五道门禁与灰度顺序——不依赖任何阿里云产品。</li></ul><h3 id="一人公司-小团队降级做法" tabindex="-1">一人公司 / 小团队降级做法 <a class="header-anchor" href="#一人公司-小团队降级做法" aria-label="Permalink to &quot;一人公司 / 小团队降级做法&quot;">​</a></h3><ul><li>归因照做：这是全篇性价比最高的一步，一张表就能避免「用训练弥补系统工程问题」。</li><li>训练降级为 prompt-only：把 SFT 的目标行为写成 few-shot 示例与检查清单；确实要微调时，用 LoRA（学习率取全参约 10 倍）在单卡上迭代。</li><li>RL 降级为「拒绝采样 + 人工抽检」：同一题让模型跑 N 次，保留通过校验的样本做 SFT 数据（DeepSeek-R1 / Qwen3 冷启动的同款思路，◇ 第三方公开做法）。</li><li>蒸馏降级为级联：小模型/便宜模型先跑，规则校验或自评不一致时升级到强模型；兜底比例与单位成功任务成本用一张表按月核算。</li></ul><hr><h2 id="卡-18-数据飞轮-先选一个业务问题-把第一轮闭环跑通" tabindex="-1">卡 18　数据飞轮：先选一个业务问题，把第一轮闭环跑通 <a class="header-anchor" href="#卡-18-数据飞轮-先选一个业务问题-把第一轮闭环跑通" aria-label="Permalink to &quot;卡 18　数据飞轮：先选一个业务问题，把第一轮闭环跑通&quot;">​</a></h2><h3 id="要解决的问题-1" tabindex="-1">要解决的问题 <a class="header-anchor" href="#要解决的问题-1" aria-label="Permalink to &quot;要解决的问题&quot;">​</a></h3><p>上线后运行记录每天都在产生，但「单次排障」无法转化为「下次直接用」；团队搭了一堆看板，却说不出哪次改动真的有效。</p><h3 id="具体做法-机制-步骤" tabindex="-1">具体做法（机制 / 步骤） <a class="header-anchor" href="#具体做法-机制-步骤" aria-label="Permalink to &quot;具体做法（机制 / 步骤）&quot;">​</a></h3><ol><li><strong>入口选最小业务问题</strong>：第一次建设调优流程时，先选一个团队确实想解决的问题（如「产品客服遗漏操作步骤」），不要一次性覆盖所有场景。</li><li><strong>六步闭环</strong>：找到真实问题 → Pipeline 持续收集 → 写成题库 → 评估器持续运行 → 新旧版本同题对比 → 采用有效方案并继续接收反馈。</li><li><strong>两条并行反馈路径</strong>：一条改进数据与判断标准（如给两类题分别写 Rubric），一条改进 Agent 行为（补 Skill、改工具描述、修重试逻辑）；两者都通过「同条件实验 + 回归」决定是否采用。</li><li><strong>认知基线</strong>：会做、做完、稳定交付是三个层次——手册引用公开基准说明「一次做对」之后还要检查重复执行（◇ τ-bench：GPT-4o 原生工具调用 pass¹ 61.2%，pass⁸ 低于 25%）。</li></ol><h3 id="前置条件-1" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件-1" aria-label="Permalink to &quot;前置条件&quot;">​</a></h3><ul><li>有一个业务负责人能确认「什么算答对」。</li><li>Trace 已能记录执行步骤与工具返回（见卡 19）。</li></ul><h3 id="适用边界-1" tabindex="-1">适用边界 <a class="header-anchor" href="#适用边界-1" aria-label="Permalink to &quot;适用边界&quot;">​</a></h3><ul><li>日流量 &lt; 50 次：先做人工抽样评审，不要铺 Pipeline。</li><li>业务规则周更：先做题库版本管理（卡 21），否则实验失去可比性。</li></ul><h3 id="反例-失败模式-1" tabindex="-1">反例 / 失败模式 <a class="header-anchor" href="#反例-失败模式-1" aria-label="Permalink to &quot;反例 / 失败模式&quot;">​</a></h3><ul><li>「搭了完整数据中台但没人用」：评估结果没有人工复核环节，样本与标准口头化。</li><li>「只看平均分上升」：关键操作题仍失败，被总体均值掩盖。</li><li>把样本数量、经验入库当收益——它们只是过程产物，有效变更进入运行后的新任务结果才是反馈。</li></ul><h3 id="可验证的效果指标-1" tabindex="-1">可验证的效果指标 <a class="header-anchor" href="#可验证的效果指标-1" aria-label="Permalink to &quot;可验证的效果指标&quot;">​</a></h3><ul><li>一轮闭环的节拍：从 trace 进 dataset 到评估器给出分数的端到端时延。</li><li>Badcase 入题库转化率；一次实验能说清「哪类题改善、哪类退化」。</li></ul><h3 id="原文引用-逐字-1" tabindex="-1">原文引用（逐字） <a class="header-anchor" href="#原文引用-逐字-1" aria-label="Permalink to &quot;原文引用（逐字）&quot;">​</a></h3><ul><li>飞轮的本质：&quot;样本数量增加、经验入库、候选生成，都还只是过程产物。有效变更进入运行以后，新任务的结果才提供下一轮反馈。&quot;</li><li>起步原则：&quot;第一次建设调优流程时，先选一个团队确实想解决的问题。&quot;</li><li>正确性的判据：&quot;对话顺利结束、接口没有报错，都不足以说明这件事办对了。&quot;</li><li>评估与调优的分工：&quot;评估负责把“好不好”落实为可检查的标准和结果；调优负责根据这些结果改变系统。&quot;</li><li>能力层次：&quot;一次做对之后，还要检查重复执行的可靠性。&quot;</li></ul><h3 id="来源-1" tabindex="-1">来源 <a class="header-anchor" href="#来源-1" aria-label="Permalink to &quot;来源&quot;">​</a></h3><p><a href="https://raw.githubusercontent.com/aliyun/ai-agent-handbook/HEAD/05-optimization/%E7%AC%AC%2018%20%E7%AB%A0%E3%80%80Agent%20%E8%B0%83%E4%BC%98%E6%80%BB%E8%A7%88.md" target="_blank" rel="noreferrer">第 18 章　Agent 调优总览</a>（18.1 持续回答的问题、18.2 数据飞轮、18.4 从一个业务问题开始）</p><h3 id="阿里云主张-第三方数据" tabindex="-1">阿里云主张 / 第三方数据 <a class="header-anchor" href="#阿里云主张-第三方数据" aria-label="Permalink to &quot;阿里云主张 / 第三方数据&quot;">​</a></h3><ul><li>◇ SWE-Bench Pro、OSWorld、OSWorld 2.0、τ-bench 等公开基准数字为手册转引的各家报告，用于说明「会做 ≠ 稳定交付」，不是企业业务成功率。</li><li>✦ 手册给出的模块关系图与「六步闭环」是阿里云产品（Agent 观测与优化控制台）的操作路径抽象；流程本身可独立复现，按钮不可。</li></ul><h3 id="一人公司-小团队降级做法-1" tabindex="-1">一人公司 / 小团队降级做法 <a class="header-anchor" href="#一人公司-小团队降级做法-1" aria-label="Permalink to &quot;一人公司 / 小团队降级做法&quot;">​</a></h3><ul><li>用一张 Notion/Excel 题库 + 每月 50 条人工抽样评审起步；评估器从 1 个 LLM-as-judge + 1 段代码规则开始。</li><li>「Baseline vs 候选」降级为「本周 vs 上周」同题对比，省去实验平台。</li><li>反馈路径只保留一条：每次改动必须能在同一批题上重放，否则不算完成一轮。</li></ul><hr><h2 id="卡-19-轨迹数据-先找到一条「自己知道发生了什么」的任务" tabindex="-1">卡 19　轨迹数据：先找到一条「自己知道发生了什么」的任务 <a class="header-anchor" href="#卡-19-轨迹数据-先找到一条「自己知道发生了什么」的任务" aria-label="Permalink to &quot;卡 19　轨迹数据：先找到一条「自己知道发生了什么」的任务&quot;">​</a></h2><h3 id="要解决的问题-2" tabindex="-1">要解决的问题 <a class="header-anchor" href="#要解决的问题-2" aria-label="Permalink to &quot;要解决的问题&quot;">​</a></h3><p>用户反馈「没解决」时，团队要在 trace 里定位：没理解需求、没找到材料，还是没用对材料。而大多数团队连「记录是否真的采到了」都没验证过。</p><h3 id="具体做法-步骤-机制" tabindex="-1">具体做法（步骤 / 机制） <a class="header-anchor" href="#具体做法-步骤-机制" aria-label="Permalink to &quot;具体做法（步骤 / 机制）&quot;">​</a></h3><ol><li><strong>第一步亲手做</strong>：跑一条自己知道答案的任务，记下 TraceID/SessionID，逐字段核对记录（输入、输出、步骤数、Tokens、耗时、工具调用与返回）。不要仅凭开关已开启就认为数据已到达。</li><li><strong>列表为空的排查顺序</strong>：先检查采集范围与筛选条件，区分「数据未采集」与「Agent 未正确执行」，避免反复发业务请求代替定位。</li><li><strong>检索策略</strong>：已知 TraceID 精确查找；连续交互用 SessionID；没有标识时按「Agent 应用 + 模型 + 工具名 + 时间窗」从少到多加条件，结果为空先撤最近加的条件。</li><li><strong>阅读顺序</strong>：目标与结果 → 概览（步骤/Token/耗时）→ 关键步骤（按工具名/关键词定位）→ 仅在怀疑字段缺失时看 JSON。结论要落到相邻事实：「用户要求操作步骤 → 检索返回了步骤 → 最终回答遗漏步骤」。</li><li><strong>三条分析路径</strong>：工具失败看失败后的行动（追问/改参/重试）；耗时与 Token 偏高先找「多出来的工作」（重复检索、过大返回），不直接删步骤；业务质检核对「回答完成」与「业务结果真完成」。</li><li><strong>三个对象边界</strong>：Trace（一次执行与调用）/ Session（一段连续交互，可能多任务）/ Trajectory（整理后的行为过程）——SessionID 不能自动证明同属一个任务。</li></ol><h3 id="前置条件-2" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件-2" aria-label="Permalink to &quot;前置条件&quot;">​</a></h3><ul><li>Trace 采集已开启，字段覆盖 step、tool call、token、耗时。</li><li>至少有一个能拿到 trace id / session id 的入口。</li></ul><h3 id="适用边界-2" tabindex="-1">适用边界 <a class="header-anchor" href="#适用边界-2" aria-label="Permalink to &quot;适用边界&quot;">​</a></h3><ul><li>日流量 &lt; 10 条：直接读 trace JSON，省去检索界面。</li><li>多 Agent 委派：必须看主子轨迹的委派关系与实际返回，不能只看子 Agent 是否结束。</li></ul><h3 id="反例-失败模式-2" tabindex="-1">反例 / 失败模式 <a class="header-anchor" href="#反例-失败模式-2" aria-label="Permalink to &quot;反例 / 失败模式&quot;">​</a></h3><ul><li>「回答里说已完成」当作任务完成——业务结果未真正落地。</li><li>「Tokens 高就压缩提示」——可能压掉必要检索上下文。</li><li>把时间接近的记录认定为同一任务——任务边界要可靠身份关联。</li></ul><h3 id="可验证的效果指标-2" tabindex="-1">可验证的效果指标 <a class="header-anchor" href="#可验证的效果指标-2" aria-label="Permalink to &quot;可验证的效果指标&quot;">​</a></h3><ul><li>一条投诉从反馈到定位到具体步骤的平均时间。</li><li>「回答完成」与「业务完成」的偏差率（可量化、可抽检）。</li></ul><h3 id="原文引用-逐字-2" tabindex="-1">原文引用（逐字） <a class="header-anchor" href="#原文引用-逐字-2" aria-label="Permalink to &quot;原文引用（逐字）&quot;">​</a></h3><ul><li>业务质检判据：&quot;Agent 回答“完成”只是一条输出；工具接收请求、任务执行结束和业务目标达成都不是同一件事。&quot;</li><li>成本分析纪律：&quot;不要仅凭总 Tokens 高就删步骤。&quot;</li><li>排查纪律：&quot;先区分数据未采集与 Agent 未正确执行，避免反复发业务请求来代替定位。&quot;</li><li>对象边界：&quot;SessionID 帮助查找相关交互，但不会自动证明它们都属于同一个任务。&quot;</li><li>Trace 的边界：&quot;适合定位某次执行和调用问题；能看到的范围取决于实际采集&quot;</li></ul><h3 id="来源-2" tabindex="-1">来源 <a class="header-anchor" href="#来源-2" aria-label="Permalink to &quot;来源&quot;">​</a></h3><p><a href="https://raw.githubusercontent.com/aliyun/ai-agent-handbook/HEAD/05-optimization/%E7%AC%AC%2019%20%E7%AB%A0%E3%80%80Agent%20%E8%BD%A8%E8%BF%B9%E6%95%B0%E6%8D%AE.md" target="_blank" rel="noreferrer">第 19 章　Agent 轨迹数据</a>（19.1 第一条任务、19.2 检索、19.3 读轨迹、19.4 三类分析、19.6 三个对象）</p><h3 id="阿里云主张-第三方数据-1" tabindex="-1">阿里云主张 / 第三方数据 <a class="header-anchor" href="#阿里云主张-第三方数据-1" aria-label="Permalink to &quot;阿里云主张 / 第三方数据&quot;">​</a></h3><ul><li>✦ AgentSpace、「数据中心 → Agent 轨迹」界面与 ATIF 轨迹格式是阿里云产品形态；「先跑一条已知任务核对字段」的方法与产品无关。</li><li>通用可复现部分：已知任务核对、检索收敛策略、阅读顺序、三条分析路径、三对象边界。</li></ul><h3 id="一人公司-小团队降级做法-2" tabindex="-1">一人公司 / 小团队降级做法 <a class="header-anchor" href="#一人公司-小团队降级做法-2" aria-label="Permalink to &quot;一人公司 / 小团队降级做法&quot;">​</a></h3><ul><li>没有 trace 系统就自己加日志：每步记录 <code>step_name, tool, args_hash, result_summary, duration_ms, tokens</code>，一个 JSONL 文件即可。</li><li>开源自托管：Langfuse / Phoenix / OpenLLMetry，两小时接入，先保证「一条已知任务能逐字段核对」。</li><li>把「找一条自己知道答案的任务」写成团队 onboarding 必做项：先会读 trace，再谈调优。</li></ul><hr><h2 id="卡-20-pipeline-把-trace-持续变成「业务能直接读的样本」" tabindex="-1">卡 20　Pipeline：把 trace 持续变成「业务能直接读的样本」 <a class="header-anchor" href="#卡-20-pipeline-把-trace-持续变成「业务能直接读的样本」" aria-label="Permalink to &quot;卡 20　Pipeline：把 trace 持续变成「业务能直接读的样本」&quot;">​</a></h2><h3 id="要解决的问题-3" tabindex="-1">要解决的问题 <a class="header-anchor" href="#要解决的问题-3" aria-label="Permalink to &quot;要解决的问题&quot;">​</a></h3><p>质检人员每天需要一张表：用户问了什么、Agent 怎么答、跑了什么操作、来自哪条 trace。而 trace 是事件级、字段是技术名词的，每次人工导出整理无法成为日常工作。</p><h3 id="具体做法-步骤-机制-指标-1" tabindex="-1">具体做法（步骤 / 机制 / 指标） <a class="header-anchor" href="#具体做法-步骤-机制-指标-1" aria-label="Permalink to &quot;具体做法（步骤 / 机制 / 指标）&quot;">​</a></h3><ol><li><strong>先定粒度再选入口</strong>：选择之前，先明确一行代表什么（一次任务 / 一次会话 / 一条并行路径）——这个决定后面所有分组、采样与评分。已有轨迹做评估选「轨迹数据」；从调用日志提业务字段选「Trace 数据」；只要问答优先「问答提取」。</li><li><strong>第一条任务只做三件事</strong>：字段投影（input / output / 轨迹 + 来源 ID）+ 明确时间范围 + 输出到指定 dataset。去重、采样、LLM 标注都先不加。</li><li><strong>预览先行</strong>：用真实样本预览，专门找「工具失败但回答成功」这类关键样本；如果过滤模块删掉了工具失败记录，调整条件保留。</li><li><strong>从单次到周期</strong>：第一轮「单次执行 + 昨天时间窗」跑通后，另起「周期执行」任务按小时/天写日常 dataset，历史补数与周期起始衔接好。</li><li><strong>按需叠加</strong>：人工复核超负荷时加随机/分组采样；没有业务标签时加 LLM 调用（分类/摘要，先供筛选，不作正式评分）；合成数据先入候选、人工确认后使用并保留来源标记。</li><li><strong>三项长期约定</strong>：样本粒度、关键字段含义、数据用途——写下来，否则换人即换口径。</li></ol><h3 id="前置条件-3" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件-3" aria-label="Permalink to &quot;前置条件&quot;">​</a></h3><ul><li>Trace 接入已完成（卡 19）。</li><li>业务负责人能确认「收到这样的表能否开始工作」。</li></ul><h3 id="适用边界-3" tabindex="-1">适用边界 <a class="header-anchor" href="#适用边界-3" aria-label="Permalink to &quot;适用边界&quot;">​</a></h3><ul><li>业务场景单一（&lt; 3 类）：无需聚类与 LLM 分类。</li><li>高基数类目（&gt; 20 类）：先 LLM 分类 + 分组采样，再人工复核。</li></ul><h3 id="反例-失败模式-3" tabindex="-1">反例 / 失败模式 <a class="header-anchor" href="#反例-失败模式-3" aria-label="Permalink to &quot;反例 / 失败模式&quot;">​</a></h3><ul><li>首次就把所有处理模块全开：出错难定位是数据范围还是加工规则。</li><li>输出 7 个字段但质检只用 1 个：配置被废弃。</li><li>LLM 标注结果直接当评分用：正式质量评分必须经可校准的评估器。</li></ul><h3 id="可验证的效果指标-3" tabindex="-1">可验证的效果指标 <a class="header-anchor" href="#可验证的效果指标-3" aria-label="Permalink to &quot;可验证的效果指标&quot;">​</a></h3><ul><li>「找到昨天的某类失败任务」查询时延（目标 &lt; 1 分钟）。</li><li>质检人员日处理样本量；Pipeline 任务成功率与平均处理时延。</li><li>输出被持续消费的比例（有人用的字段数 / 总字段数）。</li></ul><h3 id="原文引用-逐字-3" tabindex="-1">原文引用（逐字） <a class="header-anchor" href="#原文引用-逐字-3" aria-label="Permalink to &quot;原文引用（逐字）&quot;">​</a></h3><ul><li>三项约定：&quot;长期使用时，保留三项简单约定：样本粒度、关键字段含义、数据用途。&quot;</li><li>价值判据：&quot;管线简单而输出被持续使用，通常比配置了很多处理却无人消费更有价值。&quot;</li><li>粒度先行：&quot;选择之前，先明确一行代表什么。&quot;</li><li>预览纪律：&quot;如果过滤模块删掉了工具失败记录，也要调整条件。&quot;</li></ul><h3 id="来源-3" tabindex="-1">来源 <a class="header-anchor" href="#来源-3" aria-label="Permalink to &quot;来源&quot;">​</a></h3><p><a href="https://raw.githubusercontent.com/aliyun/ai-agent-handbook/HEAD/05-optimization/%E7%AC%AC%2020%20%E7%AB%A0%E3%80%80Agent%20%E8%BF%90%E8%A1%8C%E6%97%B6%E6%95%B0%E6%8D%AE%E5%A4%84%E7%90%86.md" target="_blank" rel="noreferrer">第 20 章　Agent 运行时数据处理</a>（20.1 处理选项、20.2 入口、20.3 第一条任务、20.4 采样与 AI 处理、20.5 周期化、20.6 首次交付）</p><h3 id="阿里云主张-第三方数据-2" tabindex="-1">阿里云主张 / 第三方数据 <a class="header-anchor" href="#阿里云主张-第三方数据-2" aria-label="Permalink to &quot;阿里云主张 / 第三方数据&quot;">​</a></h3><ul><li>✦ 控制台里的推荐方案卡片、Loopie 生成管线是阿里云产品能力；「先投影、再预览、后周期化」的顺序与产品无关。</li><li>通用可复现部分：粒度决策、最小首条任务、预览保留失败样本、三项约定。</li></ul><h3 id="一人公司-小团队降级做法-3" tabindex="-1">一人公司 / 小团队降级做法 <a class="header-anchor" href="#一人公司-小团队降级做法-3" aria-label="Permalink to &quot;一人公司 / 小团队降级做法&quot;">​</a></h3><ul><li>dbt + DuckDB/SQLite，每天一个 cron：视图即 Pipeline，<code>input/output/trajectory_ref/duration</code> 四列起步。</li><li>LLM 分类用 prompt + JSON schema 输出，失败人工补 50 条再迭代。</li><li>调度用 GitHub Actions / Make / n8n，不上 Airflow；「周期任务」先从每天一次开始。</li></ul><hr><h2 id="卡-21-黄金数据集-把「什么算对」沉淀为可复用题库" tabindex="-1">卡 21　黄金数据集：把「什么算对」沉淀为可复用题库 <a class="header-anchor" href="#卡-21-黄金数据集-把「什么算对」沉淀为可复用题库" aria-label="Permalink to &quot;卡 21　黄金数据集：把「什么算对」沉淀为可复用题库&quot;">​</a></h2><h3 id="要解决的问题-4" tabindex="-1">要解决的问题 <a class="header-anchor" href="#要解决的问题-4" aria-label="Permalink to &quot;要解决的问题&quot;">​</a></h3><p>每次升级临时找题、凭印象判断；团队成员对「什么算答对」各有一套标准，实验结论无法复现。</p><h3 id="具体做法-步骤-机制-1" tabindex="-1">具体做法（步骤 / 机制） <a class="header-anchor" href="#具体做法-步骤-机制-1" aria-label="Permalink to &quot;具体做法（步骤 / 机制）&quot;">​</a></h3><ol><li><strong>黄金 = 题 + 标准</strong>：题目与标准可信；Agent 曾经答错的任务，补齐正确要求后同样可以成为黄金样本——保存这类题往往比只收漂亮成功回答更有帮助。</li><li><strong>字段最小集</strong>：<code>input</code>（用户原始问题）、<code>actual_output</code>（原回答，供分析）、<code>expected_output</code>（业务认可的答案）、<code>rubric</code>（必须覆盖什么、允许什么措辞）、<code>scenario</code>（场景）、<code>source_ref</code>（来源）。</li><li><strong>两类题的要求分开写</strong>：如「有哪些功能」（能力覆盖 + 说清用途）与「如何做评估」（必须给出可执行步骤）——共用评估器会导致评分错位；Rubric 要落到字段，不能只停留在讨论里。</li><li><strong>三阶段流程</strong>：建候选集 → AI 标注 + 人工复核 → 确认的题选入黄金集 v1；证据暂缺或仍在争论的留在候选集。</li><li><strong>版本管理</strong>：重要实验或规则更新前创建版本（写明版本号与依据），比较期间不再向其追加或修改数据。</li><li><strong>三种用法</strong>：校准评估器（用好/坏/边界样本核对机器评分）、比较版本（同题跑基线 vs 候选）、长期回归（升级前重复运行）。</li><li><strong>切分原则</strong>：参与改写 Prompt、生成 Skill 或提炼经验的题，与最后独立检查效果的题分开——后者要留未参与优化的独立验证集。</li></ol><h3 id="前置条件-4" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件-4" aria-label="Permalink to &quot;前置条件&quot;">​</a></h3><ul><li>已有 Pipeline 持续产出候选样本（卡 20）。</li><li>业务负责人能给出 expected_output 与 rubric。</li></ul><h3 id="适用边界-4" tabindex="-1">适用边界 <a class="header-anchor" href="#适用边界-4" aria-label="Permalink to &quot;适用边界&quot;">​</a></h3><ul><li>业务规则日更：把变动最频繁的题隔离为「短期黄金集」，规则稳定后再固化。</li><li>高风险操作（退款、权限变更）：把「业务应达到的状态」写进 expected，不只写文本答案。</li></ul><h3 id="反例-失败模式-4" tabindex="-1">反例 / 失败模式 <a class="header-anchor" href="#反例-失败模式-4" aria-label="Permalink to &quot;反例 / 失败模式&quot;">​</a></h3><ul><li>只收低分题 → 看不到正常能力退化；只收高频题 → 漏掉代价高的少数情况。</li><li>「这题应当这么答」停在口头 → 实验无法读取。</li><li>黄金集与训练/改标题混在一起 → 间接过拟合，必须独立 held-out。</li></ul><h3 id="可验证的效果指标-4" tabindex="-1">可验证的效果指标 <a class="header-anchor" href="#可验证的效果指标-4" aria-label="Permalink to &quot;可验证的效果指标&quot;">​</a></h3><ul><li>黄金集覆盖的场景数与业务子能力数。</li><li>评估器在黄金集上的人机一致率（人工抽样对比，&gt; 80% 才信任持续评估）。</li><li>每次升级前后的退化题数（回归集）。</li></ul><h3 id="原文引用-逐字-4" tabindex="-1">原文引用（逐字） <a class="header-anchor" href="#原文引用-逐字-4" aria-label="Permalink to &quot;原文引用（逐字）&quot;">​</a></h3><ul><li>黄金的定义：&quot;“黄金”指题目与标准可信。&quot;</li><li>错题也是黄金：&quot;Agent 曾经答错的任务，只要补齐了正确要求，同样可以成为黄金样本。&quot;</li><li>训练/验证切分：&quot;参与改写 Prompt、生成 Skill 或提炼经验的题，与最后独立检查效果的题分开。&quot;</li><li>使用才算数：&quot;一份从未进入评估、实验或发布检查的数据集，即使整理得很精细，也还没有参与改进 Agent。&quot;</li><li>标准要落字段：&quot;仅在讨论中留一句“这题应当这样答”，实验并不能自动使用它。&quot;</li></ul><h3 id="来源-4" tabindex="-1">来源 <a class="header-anchor" href="#来源-4" aria-label="Permalink to &quot;来源&quot;">​</a></h3><p><a href="https://raw.githubusercontent.com/aliyun/ai-agent-handbook/HEAD/05-optimization/%E7%AC%AC%2021%20%E7%AB%A0%E3%80%80Agent%20%E9%BB%84%E9%87%91%E6%95%B0%E6%8D%AE%E9%9B%86.md" target="_blank" rel="noreferrer">第 21 章　Agent 黄金数据集</a>（21.1 用途、21.3 建设、21.4 选题、21.5 三种用法、21.6 版本与更新）</p><h3 id="阿里云主张-第三方数据-3" tabindex="-1">阿里云主张 / 第三方数据 <a class="header-anchor" href="#阿里云主张-第三方数据-3" aria-label="Permalink to &quot;阿里云主张 / 第三方数据&quot;">​</a></h3><ul><li>✦ Dataset 控制台的版本快照、AI 标注任务是产品能力；「题 + 标准」「独立验证集」「回归」是通用评估工程实践。</li><li>通用可复现部分：字段最小集、两类题分开写、三阶段流程、三种用法、切分原则。</li></ul><h3 id="一人公司-小团队降级做法-4" tabindex="-1">一人公司 / 小团队降级做法 <a class="header-anchor" href="#一人公司-小团队降级做法-4" aria-label="Permalink to &quot;一人公司 / 小团队降级做法&quot;">​</a></h3><ul><li>CSV + 版本文件夹（<code>golden_v1.csv</code>、<code>golden_v2.csv</code>）就能跑；两列起步：<code>input</code> + <code>expected</code>。</li><li>rubric 用 markdown 长文描述即可，结构化是规模化后的需求。</li><li>每次重要改动前 <code>cp golden_v1.csv golden_v1_eval_20261019.csv</code>，就是天然版本管理。</li></ul><hr><h2 id="卡-22-badcase-与评估实验-让「修过的-bug-不再回来」" tabindex="-1">卡 22　Badcase 与评估实验：让「修过的 bug 不再回来」 <a class="header-anchor" href="#卡-22-badcase-与评估实验-让「修过的-bug-不再回来」" aria-label="Permalink to &quot;卡 22　Badcase 与评估实验：让「修过的 bug 不再回来」&quot;">​</a></h2><h3 id="要解决的问题-5" tabindex="-1">要解决的问题 <a class="header-anchor" href="#要解决的问题-5" aria-label="Permalink to &quot;要解决的问题&quot;">​</a></h3><p>评估器分数一直在变，但团队说不清「哪条题修了、哪条题退了」；实验同时改模型和 Prompt，结论无法解释；修过的问题下次升级又回来。</p><h3 id="具体做法-步骤-机制-指标-2" tabindex="-1">具体做法（步骤 / 机制 / 指标） <a class="header-anchor" href="#具体做法-步骤-机制-指标-2" aria-label="Permalink to &quot;具体做法（步骤 / 机制 / 指标）&quot;">​</a></h3><ol><li><strong>评估器三件套</strong>：Code（结构/必填等确定条件）、LLM（切题与遗漏）、Agent（多步任务 + 轨迹一致性）。一个任务可挂多个评估器，但结果不能简单平均就代表业务质量。</li><li><strong>试评三件样本</strong>：至少覆盖已知好、已知坏、信息不全各一条；检查「扣分依据是否真的出现在这条回答中」「是否引用了正确的工具结果」。</li><li><strong>字段映射三步</strong>：用户问题 → 输入变量；最终回答 → 输出变量；过程判断 → 轨迹变量。需要「最终回答」的位置不能误接到某次工具调用的输出。</li><li><strong>读 Badcase 四件套</strong>：原始问题 + Agent 回答 + 分项判断 + 解释一起读；不要看到低分便立即改 Prompt——先分辨是回答完整性、评估器/映射错误，还是执行异常。</li><li><strong>实验单变量</strong>：先记录当前方案为 Baseline；若同时换模型、改 Prompt、增添 Skill，分数变化就难以解释；第一轮只改变最有依据的一项。</li><li><strong>内网 Agent 接入</strong>：SDK 在能访问业务系统的环境执行题目再回传；有会话状态的 Agent 要「创建 Session → 发送 → 取最终响应」；API 先返回任务受理时必须继续等最终回答，不能把受理成功当作题目完成。</li><li><strong>采用判定三问</strong>：严重错误是否消失，原来正常的场景是否退化，耗时与消耗是否可接受。</li><li><strong>回归闭环</strong>：确认有效的题进回归集，评估器误判进校准集，未解决留下一轮。</li></ol><h3 id="前置条件-5" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件-5" aria-label="Permalink to &quot;前置条件&quot;">​</a></h3><ul><li>黄金集已建（卡 21）。</li><li>实验能固定 Harness 与预算，仅改变一个变量。</li></ul><h3 id="适用边界-5" tabindex="-1">适用边界 <a class="header-anchor" href="#适用边界-5" aria-label="Permalink to &quot;适用边界&quot;">​</a></h3><ul><li>有状态 Agent：实验用独立 Session，避免上下文串味。</li><li>LLM 评审者：必须用人工标尺集校准，并检查长度/措辞/模型身份偏好。</li></ul><h3 id="反例-失败模式-5" tabindex="-1">反例 / 失败模式 <a class="header-anchor" href="#反例-失败模式-5" aria-label="Permalink to &quot;反例 / 失败模式&quot;">​</a></h3><ul><li>总分上升就上线：关键条款未通过被均值掩盖。</li><li>同时改 Prompt + 工具 Schema + 换模型：收益归因错位。</li><li>用「受理成功」当任务完成：题目根本没跑完。</li><li>结果出来后临时改统计口径。</li></ul><h3 id="可验证的效果指标-5" tabindex="-1">可验证的效果指标 <a class="header-anchor" href="#可验证的效果指标-5" aria-label="Permalink to &quot;可验证的效果指标&quot;">​</a></h3><ul><li>评估器人机一致率（人工抽样 50 条对比）。</li><li>Badcase → 修复 → 重测 → 确认不再回归的闭环时间。</li><li>一次实验能定位的「改善题数 vs 退化题数」。</li></ul><h3 id="原文引用-逐字-5" tabindex="-1">原文引用（逐字） <a class="header-anchor" href="#原文引用-逐字-5" aria-label="Permalink to &quot;原文引用（逐字）&quot;">​</a></h3><ul><li>单变量原则：&quot;若同时换模型、改 Prompt、增添 Skill，分数变化就难以解释；第一轮可以先只改变最有依据的一项。&quot;</li><li>采用三问：&quot;严重错误是否消失，原来正常的场景是否退化，耗时与消耗是否可接受。&quot;</li><li>映射纪律：&quot;需要“最终回答”的位置不能误接到某次工具调用的输出。&quot;</li><li>多评估器：&quot;不能把多个评估器的结果简单平均，就默认代表业务质量。&quot;</li><li>异步任务：&quot;如果 API 先返回任务受理信息，还需要继续等待最终回答，不能把受理成功当作题目完成。&quot;</li><li>排障纪律：&quot;不要看到低分便立即改 Prompt。&quot;</li></ul><h3 id="来源-5" tabindex="-1">来源 <a class="header-anchor" href="#来源-5" aria-label="Permalink to &quot;来源&quot;">​</a></h3><p><a href="https://raw.githubusercontent.com/aliyun/ai-agent-handbook/HEAD/05-optimization/%E7%AC%AC%2022%20%E7%AB%A0%E3%80%80Agent%20%E4%BC%98%E5%8C%96%EF%BC%9ABadcase.md" target="_blank" rel="noreferrer">第 22 章　Agent 优化：Badcase</a>（22.1 评估器、22.2 试评、22.3 选 Badcase、22.4 实验、22.5 本地实验、22.6 对比与采用、22.7 回归）</p><h3 id="阿里云主张-第三方数据-4" tabindex="-1">阿里云主张 / 第三方数据 <a class="header-anchor" href="#阿里云主张-第三方数据-4" aria-label="Permalink to &quot;阿里云主张 / 第三方数据&quot;">​</a></h3><ul><li>✦ 评估器三件套的配置方式、本地实验 SDK、客户侧实验平台是阿里云产品；「单变量 + 同题对比 + 回归集」是通用实验方法。</li><li>与现有页面关系：<code>ai-efficiency-practice.md</code> 的「人工审核节点」相当于本卡的纯人工版；本卡补上的是「可重复、可回归」的闭环。</li></ul><h3 id="一人公司-小团队降级做法-5" tabindex="-1">一人公司 / 小团队降级做法 <a class="header-anchor" href="#一人公司-小团队降级做法-5" aria-label="Permalink to &quot;一人公司 / 小团队降级做法&quot;">​</a></h3><ul><li>没有实验平台：每次只改一处并记录输入 hash，下一轮对比同 hash 的输出 diff。</li><li>评估器从 1 个 LLM-as-judge + 1 段人工抽样对比开始，不叠 5 个。</li><li>Badcase 用 GitHub Issues 管理，关闭前必须贴「修复 commit + 黄金集回归通过」。</li><li>「本地实验」就是自己机器上跑脚本：读 CSV 题目 → 调自己的 Agent → 写回结果，人工比对。</li></ul><hr><h2 id="卡-23-受控自进化-把「走通的方法」沉淀为-skill-资产-机制" tabindex="-1">卡 23　受控自进化：把「走通的方法」沉淀为 Skill / 资产 / 机制 <a class="header-anchor" href="#卡-23-受控自进化-把「走通的方法」沉淀为-skill-资产-机制" aria-label="Permalink to &quot;卡 23　受控自进化：把「走通的方法」沉淀为 Skill / 资产 / 机制&quot;">​</a></h2><h3 id="要解决的问题-6" tabindex="-1">要解决的问题 <a class="header-anchor" href="#要解决的问题-6" aria-label="Permalink to &quot;要解决的问题&quot;">​</a></h3><p>成功的方法只存在于老员工脑子里，下次相似问题仍从零探索；同类失败反复以不同变体重现；想上自动化又怕「自动跑偏」。</p><h3 id="具体做法-步骤-机制-2" tabindex="-1">具体做法（步骤 / 机制） <a class="header-anchor" href="#具体做法-步骤-机制-2" aria-label="Permalink to &quot;具体做法（步骤 / 机制）&quot;">​</a></h3><ol><li><strong>先判断优化层</strong>：能写成方法的就不训练模型。例：排障 Agent 查询范围过大，先在 Skill 中补充「按故障时间和对象缩小范围」；查询工具不支持过滤，才由工具维护者补能力。</li><li><strong>经验库建库三步</strong>：选应用与挖掘起始时间（覆盖成功、失败、失败后恢复）→ 抽查代表经验三件事（解决什么问题、建议什么动作、什么条件下适用）→ 回来源 Trace 确认动作真的出现过。</li><li><strong>召回接入四步</strong>：安装召回 Skill → 配经验库地址与开关 → 开必要工具权限 → 用一条已核对的经验做真实查询验收，观察 Agent 在哪一步使用了它。口头说「参考了经验」不算，要对应真实调用与执行动作。</li><li><strong>召回参数五维度</strong>：阈值、返回数量、触发时机（规划前 vs 失败后）、放置位置与长度、是否要求「经验是历史参考，采用前检查当前条件」。保留一组不使用经验的运行作 Baseline，用新 Session 重放同一请求。</li><li><strong>资产四件套（按需交付，不必一次齐）</strong>：SQL 模板（现场值参数化）、Script/工具（封装分页解析去重）、Skill（何时用、确认什么口径、字段变化怎么办）、Workflow（固定步骤接成流水线）。最大开销来自重复生成查询就先交 SQL 模板；常漏验收就先修 Skill。</li><li><strong>Badcase 推动 Skill 改进</strong>：把原 Skill + 实际失败轨迹 + 相邻成功任务 + 预期行为交给优化助手生成局部补丁；用「目标 Badcase + 原本成功的任务 + 不应触发该 Skill 的任务」三组共同验收。</li><li><strong>Harness 改进</strong>：如「提交已发生但恢复后再次提交」——区分尚未开始 / 已经开始但结果未知 / 已经完成；结果未知时先核对业务状态。这类改动是执行代码/配置，交付前要在可控环境模拟中断点验证。</li><li><strong>自动化三档</strong>：手动 → 半自动（系统整理候选、人比较与决定）→ 受控自动（规则范围内自动采用、异常交负责人）。适合先自动化的是高频、范围清楚、结果容易检查的动作。</li></ol><h3 id="前置条件-6" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件-6" aria-label="Permalink to &quot;前置条件&quot;">​</a></h3><ul><li>已有轨迹与评估器（卡 19、22）。</li><li>团队至少有 1 人熟悉业务 + 1 人熟悉 Agent 工程。</li></ul><h3 id="适用边界-6" tabindex="-1">适用边界 <a class="header-anchor" href="#适用边界-6" aria-label="Permalink to &quot;适用边界&quot;">​</a></h3><ul><li>任务样本 &lt; 100 条：经验挖掘意义有限，先写 Skill 文本。</li><li>高风险任务：经验召回先限速（条数 + 风险分级），不全量启用。</li></ul><h3 id="反例-失败模式-6" tabindex="-1">反例 / 失败模式 <a class="header-anchor" href="#反例-失败模式-6" aria-label="Permalink to &quot;反例 / 失败模式&quot;">​</a></h3><ul><li>「查询不到就扩大时间窗口」被不加条件复用：数据未接入导致永久空结果。</li><li>把「自动调优」当「自动上线」：缺少四件确认。</li><li>Skill 越写越长成为通用注意事项：真正的方法被淹没。</li><li>仅暂停挖掘却不停用旧经验：问题经验继续影响任务。</li></ul><h3 id="可验证的效果指标-6" tabindex="-1">可验证的效果指标 <a class="header-anchor" href="#可验证的效果指标-6" aria-label="Permalink to &quot;可验证的效果指标&quot;">​</a></h3><ul><li>同类任务「二次探索率」（重新查资料/试错参数的比例）下降。</li><li>召回接受率（实际采用 / 召回条数）。</li><li>自动化采用率 × 退化回滚率（看自动与人工的边界是否合适）。</li></ul><h3 id="原文引用-逐字-6" tabindex="-1">原文引用（逐字） <a class="header-anchor" href="#原文引用-逐字-6" aria-label="Permalink to &quot;原文引用（逐字）&quot;">​</a></h3><ul><li>优化层判断：&quot;排障 Agent 查询范围过大，可以先在 Skill 中补充“按故障时间和对象缩小范围”；如果查询工具不支持过滤，就由工具维护者补能力。&quot;</li><li>采用四件确认：&quot;负责人确认四件事：目标问题是否改善，原有任务是否退化，额外代价是否可接受，目标 Agent 是否实际使用了被验证的内容。&quot;</li><li>召回验收：&quot;Agent 口头说“参考了历史经验”，还需要对应真实调用和执行动作。&quot;</li><li>自动化边界：&quot;适合先自动化的，是高频、范围清楚、结果容易检查的动作。&quot;</li></ul><h3 id="来源-6" tabindex="-1">来源 <a class="header-anchor" href="#来源-6" aria-label="Permalink to &quot;来源&quot;">​</a></h3><p><a href="https://raw.githubusercontent.com/aliyun/ai-agent-handbook/HEAD/05-optimization/%E7%AC%AC%2023%20%E7%AB%A0%E3%80%80%E5%8F%97%E6%8E%A7%E8%87%AA%E8%BF%9B%E5%8C%96.md" target="_blank" rel="noreferrer">第 23 章　受控自进化</a>（23.1 选任务、23.2 经验库、23.3 召回接入、23.4 召回参数、23.5 资产化、23.6 失败样本改进、23.7 自动化三档）</p><h3 id="阿里云主张-第三方数据-5" tabindex="-1">阿里云主张 / 第三方数据 <a class="header-anchor" href="#阿里云主张-第三方数据-5" aria-label="Permalink to &quot;阿里云主张 / 第三方数据&quot;">​</a></h3><ul><li>✦ 经验召回 Skill（alibabacloud-agentloop-experience）、SkillForge 优化助手是阿里云产品；「层判断 → 资产化 → 三组验收 → 受控采用」与产品无关。</li><li>通用可复现部分：层判断、经验抽查三件事、召回五参数、资产四件套、三组验收、自动化三档。</li></ul><h3 id="一人公司-小团队降级做法-6" tabindex="-1">一人公司 / 小团队降级做法 <a class="header-anchor" href="#一人公司-小团队降级做法-6" aria-label="Permalink to &quot;一人公司 / 小团队降级做法&quot;">​</a></h3><ul><li>经验库 = 一份 markdown 知识库 + grep 或简单向量检索；「召回」就是检索后拼进上下文。</li><li>「Skill」= system prompt 里的指令块 + 一个文档目录的 RAG；「Workflow」= Make/n8n/Dify。</li><li>自动化只做「候选生成 + 实验验证」，上线人工把关；每次采用前默念四件确认。</li></ul><hr><h2 id="卡-24-边缘运行时与全球优化-什么时候该管、什么时候别管" tabindex="-1">卡 24　边缘运行时与全球优化：什么时候该管、什么时候别管 <a class="header-anchor" href="#卡-24-边缘运行时与全球优化-什么时候该管、什么时候别管" aria-label="Permalink to &quot;卡 24　边缘运行时与全球优化：什么时候该管、什么时候别管&quot;">​</a></h2><h3 id="要解决的问题-7" tabindex="-1">要解决的问题 <a class="header-anchor" href="#要解决的问题-7" aria-label="Permalink to &quot;要解决的问题&quot;">​</a></h3><p>Agent 在单一 Region 内已稳定，但用户分布全球后体验不一致：跨洋请求的网络传输可能占首 Token 延迟（TTFT）40% 以上 ✦（示例场景假设）；要不要上边缘优化？上到哪一阶段？</p><h3 id="具体做法-机制-指标" tabindex="-1">具体做法（机制 / 指标） <a class="header-anchor" href="#具体做法-机制-指标" aria-label="Permalink to &quot;具体做法（机制 / 指标）&quot;">​</a></h3><ol><li><strong>四个优化方向</strong>：延迟不对称（只有网络传输由物理距离决定，边缘就近接入命中它）、成本不透明（Token + 带宽 + 边缘请求统一计量，语义缓存卸载重复推理）、安全前置（DDoS 边缘清洗、Bot 拦截、Prompt Injection 前置初筛）、内容适配（HTML→Markdown 在边缘完成，减少二次处理延迟与 Token）。</li><li><strong>分工原则</strong>：边缘能处理的（缓存命中、安全拦截、就近路由）不回源 Region；边缘处理不了的（复杂推理、状态变更、长任务执行）才进入 Region。判断「能处理」要看事实权威、身份与权限、写副作用、数据驻留和故障恢复语义。</li><li><strong>边缘评估四维度</strong>：性能（全球各区域 TTFT P50/P95/P99）、成本（端到端调用成本、语义缓存节省量、回源流量占比）、安全（边缘拦截率、DDoS 吸收量、注入检出率）、体验（区域体验一致性、流式完整性、断连恢复成功率）。</li><li><strong>发布准入双基线</strong>：Region 内指标 + 边缘指标同时达标才允许发布。</li><li><strong>三阶段演进</strong>：阶段一边缘基础设施增强（Anycast、智能路由、DDoS 清洗、WAF/Bot、静态缓存、SSL 卸载；通常数天 ✦ 示例评估）；阶段二能力部署到边缘（语义缓存、内容转换、轻量推理）；阶段三原生边缘 Agent（EdgeFunction + RegionFunction 两级运行时 + AI 加速网关）。</li><li><strong>语义缓存纪律</strong>：只覆盖公开、幂等、低风险请求；缓存键纳入租户、权限域、地区、模型、Prompt 和知识版本；定义 TTL、失效、来源标记与回源策略，避免跨租户泄露、越权、版本陈旧与个性化误命中。</li><li><strong>全球统一基线 + 区域适配</strong>：Prompt、核心 Skill、基础安全规则全球一致；模型路由、缓存、安全规则按区域差异化——避免各区域独立演进造成能力割裂。</li><li><strong>成熟度自评 L1–L4</strong> ✦（本书归纳）：L1 无边缘优化 → L2 边缘加速独立看板 → L3 边缘指标纳入发布准入 → L4 边缘数据驱动自进化。不是越高越好，与全球化程度匹配。</li></ol><h3 id="前置条件-7" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件-7" aria-label="Permalink to &quot;前置条件&quot;">​</a></h3><ul><li>Region 内已有稳定的调优与评估体系（卡 17–23）。</li><li>已有真实跨区域流量或明确的出海计划。</li></ul><h3 id="适用边界-7" tabindex="-1">适用边界 <a class="header-anchor" href="#适用边界-7" aria-label="Permalink to &quot;适用边界&quot;">​</a></h3><ul><li>仅单区域运营：暂不需要边缘优化。</li><li>严格数据驻留：语义缓存与全球分发按区域合规配置，必要时放弃边缘缓存。</li><li>个性化强、权限敏感、时效性高的回答：不进语义缓存。</li><li>流量规模小或缓存命中率低：边缘层额外成本可能超过收益——「不优化」也是正确选择。</li></ul><h3 id="反例-失败模式-7" tabindex="-1">反例 / 失败模式 <a class="header-anchor" href="#反例-失败模式-7" aria-label="Permalink to &quot;反例 / 失败模式&quot;">​</a></h3><ul><li>「全球延迟差异大就上阶段三」：先用阶段一量化收益。</li><li>边缘缓存跨租户共享键：数据泄漏。</li><li>把「全球基线 + 区域适配」做成「每区域独立演进」：能力割裂、版本漂移。</li><li>把示例指标（EdgeFunction 冷启动 &lt;1ms、路由决策 &lt;5ms、故障转移 &lt;3s ✦ 示例目标）当成产品现状承诺。</li></ul><h3 id="可验证的效果指标-7" tabindex="-1">可验证的效果指标 <a class="header-anchor" href="#可验证的效果指标-7" aria-label="Permalink to &quot;可验证的效果指标&quot;">​</a></h3><ul><li>全球 P50/P95/P99 TTFT（分区域）；语义缓存命中率与 Token 节省率。</li><li>边缘处理请求占比（阶段三）；边缘-Region 故障转移时间。</li><li>边缘指标是否进入发布准入（L3 的判定信号）。</li></ul><h3 id="原文引用-逐字-7" tabindex="-1">原文引用（逐字） <a class="header-anchor" href="#原文引用-逐字-7" aria-label="Permalink to &quot;原文引用（逐字）&quot;">​</a></h3><ul><li>分工原则：&quot;边缘能处理的（缓存命中、安全拦截、就近路由），就不回源 Region；边缘处理不了的（复杂推理、状态变更、长任务执行），才进入 Region。&quot;</li><li>就地完成的条件：&quot;只有无需权威状态判定、无需写副作用、且符合数据驻留要求的请求才适合在边缘就地完成&quot;</li><li>发布准入：&quot;一个版本如果在全球 P95 延迟上未达标，即使 Region 内评估全部通过，也不应被发布。&quot;</li><li>阶段选择：&quot;边缘优化同样不追求最高阶段，而是根据业务的全球化程度选择成本与收益最优的阶段。&quot;</li><li>数字的性质：&quot;本章出现的所有性能数字均为示例场景假设或架构示例目标，正式实施前必须由企业基线和压测校准。&quot;</li><li>现实建议：&quot;大多数企业长期停留在阶段一或阶段二即可获得显著收益&quot;</li><li>缓存边界：&quot;语义缓存应限定在公开、幂等、低风险请求范围内&quot;</li></ul><h3 id="来源-7" tabindex="-1">来源 <a class="header-anchor" href="#来源-7" aria-label="Permalink to &quot;来源&quot;">​</a></h3><p><a href="https://raw.githubusercontent.com/aliyun/ai-agent-handbook/HEAD/05-optimization/%E7%AC%AC%2024%20%E7%AB%A0%E3%80%80Agent%20%E8%BE%B9%E7%BC%98%E8%BF%90%E8%A1%8C%E6%97%B6%E4%B8%8E%E5%85%A8%E7%90%83%E4%BC%98%E5%8C%96.md" target="_blank" rel="noreferrer">第 24 章　Agent 边缘运行时与全球优化</a>（24.1 边缘优化维度、24.2 边缘评估、24.3 性能与成本、24.5 内容分发、24.6 边缘安全、24.7 生产验证、24.8 三阶段与成熟度、24.9 能力状态与边界）</p><h3 id="阿里云团队主张-内部数据-本章最集中" tabindex="-1">阿里云团队主张 / 内部数据（本章最集中） <a class="header-anchor" href="#阿里云团队主张-内部数据-本章最集中" aria-label="Permalink to &quot;阿里云团队主张 / 内部数据（本章最集中）&quot;">​</a></h3><ul><li>✦ ESA 3200+ 边缘节点、跨洋 TTFT 占比超 40%、东京 200ms / 圣保罗 1200ms、马德里 &lt;50ms：均为示例场景假设，手册自己要求「需企业基线校准」。</li><li>✦ EdgeFunction 冷启动 &lt;1ms、路由决策 &lt;5ms、故障转移 &lt;3s、阶段一「数天」：架构示例目标 / 示例评估，非产品现状。</li><li>✦ 能力状态矩阵中「ESA 已发布 / 企业参考实现 / 实验性」的划分（含 HTML→Markdown 已发布、WebMCP 实验性）是阿里云产品口径。</li><li>✦ L1–L4 成熟度模型为本书归纳。</li><li>通用可复现部分：分工原则、边缘评估四维度、双基线准入、语义缓存纪律、三阶段选择逻辑、「成本反转时不优化」——这些是架构决策方法，不绑产品。</li></ul><h3 id="一人公司-小团队降级做法-7" tabindex="-1">一人公司 / 小团队降级做法 <a class="header-anchor" href="#一人公司-小团队降级做法-7" aria-label="Permalink to &quot;一人公司 / 小团队降级做法&quot;">​</a></h3><ul><li>不上边缘集群：用 Cloudflare/Fastly 的边缘 AI 网关或 CDN，按量付费。</li><li>跨区域只做三件事：静态结果缓存、HTML→Markdown 中间件、一套 WAF 规则。</li><li>「区域适配」= 不同 Prompt 模板 + 不同工具白名单，不做边缘运行时。</li><li>先用卡 19–22 的体系把 Region 内做好；全球化成为真实需求时，从阶段一开始，别跳级。</li></ul><hr><h2 id="全局说明-区分「阿里云主张」与「可独立复现」" tabindex="-1">全局说明：区分「阿里云主张」与「可独立复现」 <a class="header-anchor" href="#全局说明-区分「阿里云主张」与「可独立复现」" aria-label="Permalink to &quot;全局说明：区分「阿里云主张」与「可独立复现」&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>内容</th><th>使用方式</th></tr></thead><tbody><tr><td>✦ 阿里云团队主张 / 内部数据 / 示例假设</td><td>ESA 节点规模、40% TTFT、东京/圣保罗延迟、&lt;1ms/&lt;5ms/&lt;3s 示例目标、L1–L4 归纳、AgentDistill 实验、控制台操作路径</td><td>只作思路与量级参考；落地前必须用自己业务的基线与压测校准</td></tr><tr><td>◇ 第三方公开数据（手册转引）</td><td>SWE-Bench Pro 57.7%、OSWorld 75.0%/47.3%（人类 72.4%）、OSWorld 2.0 严格 20.6%、τ-bench pass¹ 61.2%/pass⁸ &lt;25%、Prodinit ~70%、FrugalGPT ~98%、DeepSeek-R1/Qwen3 冷启动做法</td><td>用于建立预期与选型参考；均附原始出处，不是本业务实测</td></tr><tr><td>通用方法（无标注）</td><td>三层归因、四类能力缺口、单位成功任务成本、RL 准入、黑白盒蒸馏、五道门禁、六步飞轮、轨迹三对象、Pipeline 三项约定、黄金集字段与切分、单变量实验、回归闭环、层判断与资产化、边缘分工原则</td><td>不依赖任何厂商产品，一人团队即可照做</td></tr></tbody></table><h2 id="维护建议" tabindex="-1">维护建议 <a class="header-anchor" href="#维护建议" aria-label="Permalink to &quot;维护建议&quot;">​</a></h2><ul><li>当《AI Agent Handbook》对应章节更新时，按「问题 / 做法 / 前置 / 边界 / 反例 / 指标 / 引用 / 降级」八段更新对应卡片。</li><li>当指标口径变化（单位成功任务成本、缓存命中率）时，同步更新卡 17 与卡 24 的「可验证的效果指标」。</li><li>新增卡片时同步追加 evidence.jsonl 行：quote_or_path 必须是来源中逐字出现、并用引号括起的片段。</li></ul><h2 id="一页速览" tabindex="-1">一页速览 <a class="header-anchor" href="#一页速览" aria-label="Permalink to &quot;一页速览&quot;">​</a></h2><ul><li>先归因再动手：卡 17（模型/Harness/环境三层）→ 卡 23（模型/Harness/方法三层）是同一种思想的两个实例。</li><li>数据生产线：卡 19（读轨迹）→ 卡 20（Pipeline 产样本）→ 卡 21（黄金集定标准）。</li><li>评估与实验：卡 22（单变量 + 回归），标准来自卡 21，样本来自卡 20。</li><li>闭环与扩展：卡 18（飞轮总纲）→ 卡 23（沉淀与受控采用）→ 卡 24（全球化，仅在有真实跨区域需求时进入）。</li></ul>',188)])])}const k=l(o,[["render",r]]);export{m as __pageData,k as default};
